p = ['src-passengers-reference', 'src-passengers-food-dialogue']
R = [record('passengers-avalon-awake-residents', 'c0366', 'Passengers — Avalon’s prematurely awakened residents', 'Passengers', 'Jim and Aurora’s continuing shipboard household', ['movie'],
    scope('Finished 2016 film', 'The prematurely awakened pair’s continuing residence, including life after the reactor repair', 'Jim and Aurora while alive and awake aboard Avalon', ['Hibernating colonists and crew as leisure citizens', 'Gus as a durable third resident', 'An established Homestead II economy', 'Different events in early screenplay drafts']),
    'Jim and Aurora become long-term residents of a largely automatic passenger environment, with living space, meals, entertainment and medical machinery already operating around them. Their continuing support is not paid out of current wages. This makes the pair a narrow post-work household comparison rather than a claim about all future humanity. Passenger class affects food privileges, and serious malfunctions threaten even basic survival, so the guarantee estimate is moderately strong rather than unlimited or secure under every condition.\n\nThe ship’s services enforce a designed hierarchy of passenger and employee permissions. That supports a concentrated institutional-control estimate near zero; a talking interface and automatic flight do not establish an independent AI sovereign. Gus’s employee access helps the pair reach systems that their passenger status cannot command. Human work also remains indispensable when the reactor fails, and Aurora continues writing. Their later home does not supply an exact lifetime participation rate. Sleeping travelers and people not yet born are excluded from the denominator, while the eventual successful voyage is not proof of a post-work colony at its destination.',
    {'guarantees': -0.45, 'control': 0.05, 'nonworking': None},
    {'guarantees': assessment(-0.45, [-0.8, 0.2], 'low', 'Long-term automatic passenger services support the awake pair without current wages, but class restrictions, failed hibernation and infrastructure breakdown qualify security.', p),
     'control': assessment(0.05, [0, 0.2], 'medium', 'Access follows concentrated passenger/employee permissions; the ship interface is not shown to own the infrastructure or set an autonomous political constitution.', p),
     'nonworking': assessment(None, None, 'low', 'Writing, maintenance and emergency repair remain useful work; neither continuous leisure nor a stable work census follows from the long time aboard.', p)},
    1, p, [evidence('The pair remain awake with ship services, repair the failing reactor and subsequently live out their lives aboard.', p, 'Finished-film plot and breakfast-class dialogue', 'secondary_reference_and_primary_dialogue')],
    ['An accidental but continuing two-human supported household, not a temporary holiday or proof of universal welfare.', 'Infrastructure repair is actual human work, not dispensable make-work.', 'The guarantee interval reflects both provision and severe technical failure.', 'Neither sleeping population ratios nor unknown later descendants create a participation estimate.'])]
