    decision('c0368', 'needs_evidence', 'UTS privilege and excluded salvage workers do not establish the elite’s labor-independent provisioning mechanism.', ['src-space-sweepers-netflix'], analysis='The official synopsis establishes inequality and useful paid work, not automatic necessities or productive ownership beyond corporate setting.', follow_up='Skip deeper lore; do not convert noncitizenship into nonemployment.'),
    decision('c0369', 'boundary_case', 'Jung_E depicts real industrial and human-derived military work rather than a demonstrated general post-work support order.', ['src-jung-e-reference'], analysis='A contract buying brain data and paying one family’s expenses does not establish population-wide work independence.', follow_up='Keep as a cognitive-labor and personhood comparison.'),
    decision('c0370', 'boundary_case', 'Vesper’s seed monopoly still depends on real subsistence and biological production work.', ['src-vesper-reference'], analysis='Artificial scarcity and wealth are not sufficient for a zero variant without available replacement of the relevant productive labor.', follow_up='Keep as a biotechnology monopoly comparison; do not infer an unseen citadel welfare constitution.'),
    decision('c0371', 'needs_evidence', 'Noctis’s mixed human-robot society does not have a verified work-independent access system in the quick reference.', ['src-mars-express-plot'], analysis='Brain farms and detective work establish actual activity and exploitation, not a general provisioning mechanism.', follow_up='Skip deeper film reconstruction.'),
    decision('c0372', 'needs_evidence', 'The departing robots do not yet have a verified settled material-access constitution.', ['src-mars-express-ending'], analysis='Carlos’s human-derived identity prevents treating all participants as mere hardware, but departure and autonomy still do not establish support rights or the active community’s economic rules.', follow_up='Do not manufacture a new regime from the destination left unspecified.'),
    decision('c0373', 'needs_evidence', 'Draag technology and Om subordination do not establish an automatic provision system for a scoped population.', ['src-fantastic-planet-reference'], analysis='Meditation is not a nonworking census, and kept humans and wild Oms cannot be assigned identical access rights.', follow_up='Skip deeper film or source-novel reading.'),
    decision('c0374', 'needs_evidence', 'Gandahar’s plentiful food and engineered organisms do not resolve productive labor or distribution.', ['src-gandahar-review'], analysis='The ecological utopia has excluded experimental populations, and abundance does not itself show that work has ceased to allocate necessities.', follow_up='Skip a full viewing or novel reconstruction; do not mistake biological technology for literal absence of technology.'),
    decision('c0375', 'boundary_case', 'Metamorphis uses captive people as biological resources rather than supporting a human post-work community.', ['src-gandahar-reference'], analysis='Machine servants do not make their controller an AI or their human victims leisured beneficiaries.', follow_up='Keep as a predatory-production comparison.'),
    decision('c0376', 'needs_evidence', 'Alpha 60’s control over thought and behavior does not establish Alphaville’s automatic material economy.', ['src-alphaville-reference'], analysis='An AI ruler can coexist with many different labor and distribution systems; the checked account does not settle which one applies.', follow_up='Skip deeper film reconstruction.')
